namespace WoodLounge.Domain.Common;

/// <summary>
/// Base for entities with a uuid PK. Ids are generated by Postgres (gen_random_uuid())
/// via the default value configured in Infrastructure; set here only for in-memory use.
/// </summary>
public abstract class Entity
{
    public Guid Id { get; set; }
}

/// <summary>Entity with created_at + updated_at maintained by EF (SaveChanges interceptor).</summary>
public abstract class AuditedEntity : Entity
{
    public DateTimeOffset CreatedAt { get; set; }
    public DateTimeOffset UpdatedAt { get; set; }
}
